SELECT COUNT(*) FROM badges as b, posts as p, votes as v, users as u WHERE p.OwnerUserId = u.Id AND v.UserId = u.Id AND b.UserId = u.Id AND b.Date<='2014-08-25 19:05:46'::timestamp AND p.Score>=-1 AND p.Score<=29 AND p.CreationDate>='2010-07-19 20:40:36'::timestamp AND p.CreationDate<='2014-09-10 20:52:30'::timestamp AND v.BountyAmount<=50;